// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Whether temporary-password emails can be sent (whether ACCOUNT_SMTP_* was set at deployment); returns no settings
	// (GET /account-mail)
	GetAccountMailStatus(w http.ResponseWriter, r *http.Request)
	// Names of allowlisted transaction addresses (the platform's own address book, never written to nodes), as a map of lowercase address -> name, listing only named addresses
	// (GET /account-names)
	ListAccountNames(w http.ResponseWriter, r *http.Request)
	// Clear the name of an allowlisted transaction address
	// (DELETE /account-names/{address})
	DeleteAccountName(w http.ResponseWriter, r *http.Request, address string)
	// Name an allowlisted transaction address (saved immediately, independent of applying the list)
	// (PUT /account-names/{address})
	SetAccountName(w http.ResponseWriter, r *http.Request, address string)
	// List alert rules (default rules together with user-added rules)
	// (GET /alert-rules)
	ListAlertRules(w http.ResponseWriter, r *http.Request)
	// Restore default rules (nodes:onboard). Default rules are reset to their default values and re-enabled. User-added rules are not affected. Default rules cannot be deleted (user-added rules can be deleted in Enterprise), and the platform recreates any missing default rule on every startup.
	// (POST /alert-rules/restore-defaults)
	RestoreDefaultAlertRules(w http.ResponseWriter, r *http.Request)
	// Update an alert rule (full replacement; nodes:onboard). Which fields can change depends on kind; see AlertRuleUpdateRequest
	// (PUT /alert-rules/{id})
	UpdateAlertRule(w http.ResponseWriter, r *http.Request, id string)
	// Current alert notification settings (the SMTP password is never returned). Without nodes:onboard, webhook urls are empty strings (only the number of webhooks is visible)
	// (GET /alert-settings)
	GetAlertSettings(w http.ResponseWriter, r *http.Request)
	// Set the language and time zone of alert notifications (nodes:onboard). Platform-wide: every channel uses them, and the default rules' summaries and descriptions are written in the same language. Saving rewrites alertmanager.yml, and a language change also rewrites the Prometheus rules file; channels are not affected.
	// (PUT /alert-settings/locale)
	PutAlertSettingsLocale(w http.ResponseWriter, r *http.Request)
	// Disable Slack notifications and clear the stored settings (nodes:onboard).
	// (DELETE /alert-settings/slack)
	DeleteAlertSettingsSlack(w http.ResponseWriter, r *http.Request)
	// Configure and enable Slack notifications (nodes:onboard). Only Slack changes; other channels are not affected. webhookUrl is required (the URL itself is the credential and GET never returns it); the host must be hooks.slack.com or hooks.slack-gov.com.
	// (PUT /alert-settings/slack)
	PutAlertSettingsSlack(w http.ResponseWriter, r *http.Request)
	// Disable Email (SMTP) notifications and clear the stored settings (nodes:onboard). The webhook list is not affected.
	// (DELETE /alert-settings/smtp)
	DeleteAlertSettingsSmtp(w http.ResponseWriter, r *http.Request)
	// Configure and enable Email (SMTP) notifications (nodes:onboard). Only SMTP changes; the webhook list is untouched. Notification settings are split into one endpoint per channel so that changing one channel does not require resending another channel's settings. password is required when username is set; without a username (a relay that takes no login) it may be empty and is not stored. "Leave blank to keep the current password" is not supported; the full settings are sent every time so the operator never has to guess which password is stored.
	// (PUT /alert-settings/smtp)
	PutAlertSettingsSmtp(w http.ResponseWriter, r *http.Request)
	// Disable Telegram notifications and clear the stored settings (nodes:onboard).
	// (DELETE /alert-settings/telegram)
	DeleteAlertSettingsTelegram(w http.ResponseWriter, r *http.Request)
	// Configure and enable Telegram notifications (nodes:onboard). Only Telegram changes; other channels are not affected. botToken is required for the same reason as the SMTP password: "leave blank to keep the current token" is not supported.
	// (PUT /alert-settings/telegram)
	PutAlertSettingsTelegram(w http.ResponseWriter, r *http.Request)
	// Test the Slack webhook (nodes:onboard). Sends a test message to the webhook. It uses the current form contents, so there is no need to save first.
	// (POST /alert-settings/test-slack)
	TestAlertSettingsSlack(w http.ResponseWriter, r *http.Request)
	// Test the SMTP connection (nodes:onboard, same as PUT /alert-settings/smtp). Only does a TCP connection plus credential check and sends no mail, because testing settings should not bother real recipients. It connects with the chosen `security` and picks the AUTH mechanism the way Alertmanager does (the first of the server's advertised mechanisms it knows), so a passing test means Alertmanager can send with the same settings. It uses the current form contents, not the saved settings, so there is no need to click "Save" before testing.
	// (POST /alert-settings/test-smtp)
	TestAlertSettingsSmtp(w http.ResponseWriter, r *http.Request)
	// Test the Telegram settings (nodes:onboard). Verifies the bot token, then sends a test message to the chat. Unlike webhooks, which only test the connection, Telegram has a fixed format, and actually sending a message is the only way to confirm the bot has joined the group. It uses the current form contents, so there is no need to save first.
	// (POST /alert-settings/test-telegram)
	TestAlertSettingsTelegram(w http.ResponseWriter, r *http.Request)
	// Test a webhook connection (nodes:onboard, same as PUT /alert-settings/webhooks). Only does a TCP connection plus (for https) a TLS handshake and sends no HTTP request. Alertmanager actually sends its own webhook JSON schema, not the Slack {text:...} format, and what the remote server does with a payload is beyond our control; stopping at the connection layer is the only way to guarantee no visible action is triggered. It uses the current form contents, so there is no need to click "Save" before testing.
	// (POST /alert-settings/test-webhook)
	TestAlertSettingsWebhook(w http.ResponseWriter, r *http.Request)
	// Replace the whole custom webhook list (nodes:onboard). Only webhooks change; SMTP settings are untouched. Sending an empty array clears all webhooks.
	// (PUT /alert-settings/webhooks)
	PutAlertSettingsWebhooks(w http.ResponseWriter, r *http.Request)
	// List this organization's alerts (Prometheus rules -> Alertmanager -> stored via webhook ingestion)
	// (GET /alerts)
	ListAlerts(w http.ResponseWriter, r *http.Request, params ListAlertsParams)
	// Mark the current entry of each of these alerts as read by the current user. A firing alert marks its firing entry; a resolved alert marks both its firing and resolved entries. Unknown or malformed ids are ignored
	// (POST /alerts/read)
	MarkAlertsRead(w http.ResponseWriter, r *http.Request)
	// Mark all alerts within the retention period as read by the current user (according to each alert's state)
	// (POST /alerts/read-all)
	MarkAllAlertsRead(w http.ResponseWriter, r *http.Request)
	// Login page settings (whether to show the password form and the SSO button)
	// (GET /auth/config)
	GetAuthConfig(w http.ResponseWriter, r *http.Request)
	// Password login (local account, or the LDAP connector when one is set up; sets the session cookie)
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Login history (one entry per login attempt, newest first; not part of the audit log and also available in the open-source edition; kept for 90 days)
	// (GET /auth/login-events)
	ListLoginEvents(w http.ResponseWriter, r *http.Request, params ListLoginEventsParams)
	// Log out (clears the session)
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Change your own password; the UI calls it only for the forced password change on first login
	// (POST /auth/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// Chain-level info (taken from this organization's healthy node with the highest block height)
	// (GET /chain)
	GetChainInfo(w http.ResponseWriter, r *http.Request)
	// Nodes on the chain (validator set ∪ this organization's nodes ∪ nodes seen in their admin_peers), validators first
	// (GET /chain/nodes)
	ListChainNodes(w http.ResponseWriter, r *http.Request)
	// Nodes whose agent the platform cannot reach (lists only nodes that have been unreachable for at least 10 minutes)
	// (GET /fleet/status)
	GetFleetStatus(w http.ResponseWriter, r *http.Request)
	// List join tokens (secrets excluded)
	// (GET /join-tokens)
	ListJoinTokens(w http.ResponseWriter, r *http.Request)
	// Create a join token (single use; the secret appears only once, in this response)
	// (POST /join-tokens)
	CreateJoinToken(w http.ResponseWriter, r *http.Request)
	// Revoke a join token (pending or expired tokens can both be revoked; the record is kept)
	// (POST /join-tokens/{id}/revoke)
	RevokeJoinToken(w http.ResponseWriter, r *http.Request, id string)
	// Add to the shared list. The platform does not judge who the peer is or whether to connect; that is the user's responsibility (it may be a node of this organization, with the address supplied by the user)
	// (POST /manual-peers)
	CreateManualPeer(w http.ResponseWriter, r *http.Request)
	// Remove from the shared list (the next round calls admin_removePeer on nodes using the shared list)
	// (DELETE /manual-peers/{pubkey})
	DeleteManualPeer(w http.ResponseWriter, r *http.Request, pubkey string)
	// Current user (the user resolved by SSO + platform roles + organization)
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// List this organization's nodes
	// (GET /nodes)
	ListNodes(w http.ResponseWriter, r *http.Request)
	// Delete a node (revokes all its valid certificates so the agent disconnects within 5s; removes the node record and settings)
	// (DELETE /nodes/{id})
	DeleteNode(w http.ResponseWriter, r *http.Request, id string)
	// Get node details
	// (GET /nodes/{id})
	GetNode(w http.ResponseWriter, r *http.Request, id string)
	// Get alerts for one node (local alerts table)
	// (GET /nodes/{id}/alerts)
	GetNodeAlerts(w http.ResponseWriter, r *http.Request, id string)
	// Clear the addresses added directly to this node. Written to the node first and saved only if the read-back matches (the use-shared-list switch is unchanged)
	// (DELETE /nodes/{id}/allowlist)
	DeleteNodeAllowlist(w http.ResponseWriter, r *http.Request, id string)
	// Set the addresses added directly to this node (on top of the shared list). They are written to the node first and saved only if the read-back matches
	// (PUT /nodes/{id}/allowlist)
	SetNodeAllowlist(w http.ResponseWriter, r *http.Request, id string)
	// Set whether this node uses the shared list. Written to the node first and saved only if the read-back matches
	// (PUT /nodes/{id}/allowlist/shared)
	SetNodeAllowlistShared(w http.ResponseWriter, r *http.Request, id string)
	// Reapply, i.e. push the platform's effective list (shared list ∪ directly added) to this node again, adding what is missing and removing what is extra
	// (POST /nodes/{id}/allowlist/sync)
	SyncNodeAllowlist(w http.ResponseWriter, r *http.Request, id string)
	// Get node certificate and connection status (top of the node settings page)
	// (GET /nodes/{id}/cert)
	GetNodeCert(w http.ResponseWriter, r *http.Request, id string)
	// Extra peers for this node, i.e. the use-shared-list switch and peers added to this node directly
	// (GET /nodes/{id}/custom-peers)
	GetNodeCustomPeers(w http.ResponseWriter, r *http.Request, id string)
	// Add a peer directly to this node (may be a node of this organization but not this node itself; allowed whether or not the switch is on; admin_addPeer runs next round)
	// (POST /nodes/{id}/custom-peers)
	CreateNodeCustomPeer(w http.ResponseWriter, r *http.Request, id string)
	// Remove from this node's directly added peers (admin_removePeer runs next round)
	// (DELETE /nodes/{id}/custom-peers/{pubkey})
	DeleteNodeCustomPeer(w http.ResponseWriter, r *http.Request, id string, pubkey string)
	// Change a node's log level (admin_changeLogLevel; takes effect immediately but is not persisted, and a Besu restart reverts to logging in config.toml)
	// (PUT /nodes/{id}/log-level)
	SetNodeLogLevel(w http.ResponseWriter, r *http.Request, id string)
	// Recent Besu logs of a node (read from the agent's in-memory buffer through the agent tunnel; the platform stores nothing)
	// (GET /nodes/{id}/logs)
	GetNodeLogs(w http.ResponseWriter, r *http.Request, id string, params GetNodeLogsParams)
	// Set the display name of a node in this organization (non-ASCII such as Chinese allowed; the node id does not change)
	// (PUT /nodes/{id}/name)
	SetNodeName(w http.ResponseWriter, r *http.Request, id string)
	// Set whether this node uses the shared list. The setting is saved first, then admin_addPeer / admin_removePeer is pushed to this node once right away; a failed push is not an error, the next background round (within 30 seconds) resends it anyway. Directly added peers are untouched. The push happens even if the value did not change
	// (PUT /nodes/{id}/peer-shared)
	SetNodePeerShared(w http.ResponseWriter, r *http.Request, id string)
	// List the peers this node is currently connected to (read from the node's own admin_peers; only peers that completed the handshake are listed). monitor:view is enough to see them, including public key, enode and remote address; cross-organization forwarding has no logged-in user and omits those three fields
	// (GET /nodes/{id}/peers)
	ListNodePeers(w http.ResponseWriter, r *http.Request, id string)
	// Change the node's local RPC and metrics ports (the targets the platform forwards to through the agent tunnel)
	// (PUT /nodes/{id}/ports)
	SetNodePorts(w http.ResponseWriter, r *http.Request, id string)
	// Get time series for one node (charts)
	// (GET /nodes/{id}/series)
	GetNodeSeries(w http.ResponseWriter, r *http.Request, id string, params GetNodeSeriesParams)
	// Snapshot of this node's transaction pool (node RPC is queried live only while the tab is open; the platform stores nothing)
	// (GET /nodes/{id}/txpool)
	GetNodeTxPool(w http.ResponseWriter, r *http.Request, id string, params GetNodeTxPoolParams)
	// Clear a node's name
	// (DELETE /peer-names/{address})
	DeletePeerName(w http.ResponseWriter, r *http.Request, address string)
	// Name a node, keyed by address (the peers page derives the address from the public key and the validators page uses the address directly, so both show the same name)
	// (PUT /peer-names/{address})
	SetPeerName(w http.ResponseWriter, r *http.Request, address string)
	// Current account allowlist and the detection result for each node
	// (GET /permissioning)
	GetPermissioningPolicy(w http.ResponseWriter, r *http.Request)
	// Set the shared account allowlist (after saving, perm_* RPCs are sent right away to nodes using the shared list and the result is read back and compared)
	// (PUT /permissioning)
	SetPermissioningPolicy(w http.ResponseWriter, r *http.Request)
	// Agent installation info (install.sh checksum, offline bundle file name and checksum)
	// (GET /platform/agent-bundle)
	GetAgentBundle(w http.ResponseWriter, r *http.Request)
	// Public key the platform uses to sign node RPC tokens (public endpoint; node operators point Besu's --rpc-http-authentication-jwt-public-key-file at it)
	// (GET /platform/rpc-public-key)
	GetPlatformRpcPublicKey(w http.ResponseWriter, r *http.Request)
	// Besu RPC method catalog (source for the checkbox list and the backend's permission-validation allowlist; follows the Besu version)
	// (GET /rpc-method-catalog)
	GetRpcMethodCatalog(w http.ResponseWriter, r *http.Request)
	// List this organization's RPC access identities (named sets of method permissions, shared across the organization; the platform stores no passwords, you issue a token to use one)
	// (GET /rpc-users)
	ListRpcUsers(w http.ResponseWriter, r *http.Request)
	// Create an RPC access identity (stores only the name and method permissions; tokens are issued separately via /token)
	// (POST /rpc-users)
	CreateRpcUser(w http.ResponseWriter, r *http.Request)
	// Delete an RPC access identity and its history (no further tokens are issued; nodes still accept already issued tokens until exp)
	// (DELETE /rpc-users/{id})
	DeleteRpcUser(w http.ResponseWriter, r *http.Request, id string)
	// Activity history of an RPC access identity (creation, token issuance; newest first)
	// (GET /rpc-users/{id}/events)
	ListRpcUserEvents(w http.ResponseWriter, r *http.Request, id string)
	// Issue a JWT for this user (RS256 with the platform private key; permissions = the user's current method permissions; exp is required because Besu rejects tokens without exp)
	// (POST /rpc-users/{id}/token)
	IssueRpcUserToken(w http.ResponseWriter, r *http.Request, id string)
	// Connection state of the shared list, per-node usage, and candidates that can be added to the list
	// (GET /shared-peers)
	ListSharedPeers(w http.ResponseWriter, r *http.Request)
	// List local users
	// (GET /users)
	ListLocalUsers(w http.ResponseWriter, r *http.Request)
	// Create a local user. The temporary password is always generated by the system. By default it appears once in the response for the admin to hand over; with sendEmail it is mailed to email (see GET /account-mail). A password change is forced on first login
	// (POST /users)
	CreateLocalUser(w http.ResponseWriter, r *http.Request)
	// Delete a local user (all logged-in sessions are logged out; audit records are kept separately)
	// (DELETE /users/{username})
	DeleteLocalUser(w http.ResponseWriter, r *http.Request, username string)
	// Disable / enable a user (disabling logs out all of the account's sessions). The role is fixed at creation and cannot be changed
	// (PATCH /users/{username})
	UpdateLocalUser(w http.ResponseWriter, r *http.Request, username string)
	// Reset a password. The new password is always generated by the system and delivered the same way as for a new user. After a reset all sessions are logged out, a password change is forced on next login, and the failure count is cleared
	// (POST /users/{username}/reset-password)
	ResetLocalUserPassword(w http.ResponseWriter, r *http.Request, username string)
	// Changes under vote, i.e. votes written into blocks this epoch (network-wide) plus votes our own nodes have cast that are not yet in a block, grouped by target address and direction. Once a change takes effect it shows in the validator set and the row disappears
	// (GET /validator-votes)
	ListValidatorVotes(w http.ResponseWriter, r *http.Request)
	// Cast a vote on each of our own validator nodes (*_proposeValidatorVote). No record is created and nothing is re-voted in the background; other organizations vote on their own platforms
	// (POST /validator-votes)
	ProposeValidatorVote(w http.ResponseWriter, r *http.Request)
	// Finished validator votes, newest first (recorded by the platform from on-chain votes, starting from the epoch in which the platform began watching)
	// (GET /validator-votes/history)
	ListValidatorVoteHistory(w http.ResponseWriter, r *http.Request)
	// Withdraw this organization's vote for this address on each of our own validator nodes
	// (DELETE /validator-votes/{address})
	DiscardValidatorVote(w http.ResponseWriter, r *http.Request, address string)
	// Current validator set (read-only, aggregated from the consensus state each node reports)
	// (GET /validators)
	ListValidatorSet(w http.ResponseWriter, r *http.Request)
}

